#include <iostream>
using namespace std;

int main() {
    int N, M;
    char A, B, C;
    char converse[256]; // Use a fixed-size array for characters

    do {
        cin >> N;
        if (N == 0) break;

        // Initialize converse array
        for (int i = 0; i < 256; i++) {
            converse[i] = i; // Direct assignment for ASCII values
        }

        for (int i = 0; i < N; i++) {
            cin >> A >> B;
            converse[A] = B;
        }

        cin >> M;
        for (int i = 0; i < M; i++) {
            cin >> C;
            printf("%c", converse[C]);
        }
        printf("\n");
    } while (N != 0);

    return 0;
}

